def deob(text):
    t = re.sub(r"\s*\[\s*at\s*\]\s*", "@", text or "", flags=re.I)
    t = re.sub(r"\s*\[\s*dot\s*\]\s*", ".", t, flags=re.I)
    t = re.sub(r"\[\s*in\s*\]\s*$", ".in", t.strip(), flags=re.I)  # gov[in]
    t = re.sub(r"\[|\]", "", t)
    return t.strip(" .,;")

